class parameters:

    def __init__(self):
                
        ################ chosen model ##################
        self.model = 'RSF_METABRIC'  #in ['LogReg_clin', 'MLP_clin', 'MLP_clin_graph', 'MLP_img', 'MLP_clin_img', 'MLP_clin_largest', 'MLP_largest', 'MIL_img', 'GraphConv_img', 'GAT_img'] #Not considered when feat_version is METABRIC or SUPPORT
        self.LogReg_list = ['LogReg_clin']
        self.MLP_list = ['MLP_clin', 'MLP_clin_graph', 'MLP_clin_img', 'MLP_img', 'MLP_clin_largest', 'MLP_largest'] #'MLP_clin_graph' not usable anymore
        self.MIL_list = ['MIL_img'] 
        self.GNN_list = ['GraphConv_img', 'GAT_img']
        self.METsurv_list = ['XGB_METABRIC', 'RSF_METABRIC'] #XGboost or RSF, usable only with METABRIC! (experimental: XGB not functional)

        ################ chosen data ##################
        feat_version =  'METABRIC' #['featv1', 'featv2', 'featv3', 'featv4', 'featv5', 'METABRIC', 'SUPPORT']  #v1: Aswathi's type; v2: bounding box+robust features; v3: segmentation (maj vote)+robust features; v4:bounding box+all Gauthier's features; v5: segmentation (SUV4)+robust features; METABRIC and SUPPORT are two usual survival datasets from pycox (/!\: they directly use a MLP whatever self.model is) (and usable only with CoxTime loss function)
        self.pat_to_use = 'patfull561' #['patAsw545', 'patfull561', 'patAsw583']
        self.mean5tests = True #whether to consider as result the mean of the results over 5 different splits of test (each with 10 loops of training and validation) (True), or to consider only the results from one test set (False) 
        self.sameSplit561As583 = False #whether we use, when self.pat_to_use=='patfull561', the same validation and test sets as when self.pat_to_use=='patAsw583' (/!\: only when 10 loops + shouldn't be used when self.mean5tests=True (otherwise self.mean5tests will be useless))
        self.saving_results = True  #to choose whether or not to save the results in tensorboard and in a text file   
        self.clin_onehot = False #Whether to use one-hot labels for categorical clinical variables (only for conf3)
        gsearch = False #Whether we do a gridsearch or a single test

        self.largest = True if(self.model=='MLP_clin_largest' or self.model=='MLP_largest') else False #Whether we use a single lesion (the largest) or all of them for each patient: do not modify
        
        
        ################ global learning params ##################
        self.n_loops = 10  #number of independent trials for each test
        self.early_stopping = True #True to use early stopping and False to not use it
        self.prop_val = 0.10  #proportion of validation samples
        self.prop_test = 0.10  #proportion of test samples
        self.batch_size = 4 #Not clean: sometimes this one is used, or the ones directly in the dict corresponding to each model: just always let them to 4
        self.scaler = 'stand_scaler' #Scaler to be used in ['stand_scaler', 'rob_scaler'] (for StandardScaler() and RobustScaler() (sklearn modules))
        self.loss_fct = 'CoxTime' #Loss function to use, between those in self.classif_list and those in self.survival_list (only BCE usable here)
        self.stratif = 'stratifcens' #Stratification of the data in ['nostratif', 'stratif2yPFStest', 'stratifcens'] (for -no stratification, -stratify the test set (and not the validation and training sets) by the 2 year-PFS binary label, -stratify all the sets by the censoring/event label); only applied if we use a survival loss function ('stratif2yPFStest' unusable with METABRIC and SUPPORT datasets (do not have a binary two-year PFS))
        self.discretization_scheme = 'quantiles' #Scheme for the discretization of the time when using discrete survival loss functions, in ['equidistant', 'quantiles']
        self.n_time_intervals = 10 #Number of time intervals for discrete survival analysis functions and to plot Brier score for continuous survival analysis functions

        self.classif_list = ['BCE'] #BCE = Binary Cross-Entropy
        self.survival_list = ['DeepHitS','CoxTime','DeepSurv'] 



        ################ paths ##################     
        self.PIK_graphs = "./files_to_load/graphs_knn_final.dat"#
        self.PIK_dmax = "./files_to_load/dmax_list.dat"         #
        surv = '' if(self.loss_fct not in self.survival_list) else '_surv'
        self.DB = f"./files_to_load/new_dataset_{feat_version}{surv}-nonan.csv" if(not self.largest) else f"./files_to_load/new_dataset_{feat_version}{surv}-largest.csv"
        if(feat_version=='METABRIC' or feat_version=='SUPPORT'): self.DB = feat_version
        elif(self.pat_to_use == 'patAsw583'): self.DB = f"./files_to_load/new_dataset_{feat_version}{surv}-complete.csv"
        self.PIK_dump_graph = "./save/graph_array.dat"
        self.PIK_dump_g_features = "./save/graph_features.npy" 



        ################ learning hyperparameters ##################
        #LogReg:
        batch_size_LogReg = [4] #[4,5,6,7]
        C_opt_LogReg = [10] if(not gsearch) else [0.0001, 0.001, 0.01, 0.1, 1, 10]
        l1_ratio_LogReg = [0] if(not gsearch) else [0, 0.25, 0.5, 0.75, 1]
        nb_epochs_LogReg = [1]
        self.params_LogReg = {'batch_size': batch_size_LogReg,
                             'C_opt': C_opt_LogReg,
                             'l1_ratio': l1_ratio_LogReg,
                             'nb_epochs': nb_epochs_LogReg}

        #MLPs:
        self.MLP2lay = False  #Whether to use (True) 2 layers in the MLP models or (False) 3 layers
        batch_size_MLP = [4] #[4,5,6,7]
        hidden_channels_MLP = [16] if(not gsearch) else [16,32,64,128] #[32] #[16,32,64,128] #[32]
        learning_rates_MLP = [0.1] if(not gsearch) else [0.1,0.01,0.001,0.0001] #[0.01] #[0.1,0.01,0.001,0.0001] #[0.001]
        nb_epochs_MLP = [100]
        self.params_MLP = {'batch_size': batch_size_MLP,
                           'hidden_channels': hidden_channels_MLP,
                           'learning_rates': learning_rates_MLP,
                           'nb_epochs': nb_epochs_MLP}
        
        #MLP METABRIC/SUPPORT:
        batch_size_MLP_METSUP = [4] #[4,5,6,7]
