        nb_epochs_GNN = [100]
        alpha_GNN = [1] if(not gsearch) else [0.1,1,10,50] #[0.1,1,10,50] #[50] #[0.1,1,5,10,50,100]
        self.edge_weights_GNN = True #True or False: whether we consider weighted edges. If False, alpha will not have any effect on the results.
