        self.GNN1lay = False  #Whether to use (True) 1 layer in the GNN models or (False) 2 layers
        self.sep_edge_weights = False #True or False: whether we consider as edge weights the product of the distance between the lesions and the distance between their features (False), or we consider them separately (True).
